"""Competing behavior policies with an observation-only interface.

These policies parse public text. They receive neither an engine nor a world seed.
The reference methods on trusted engines are separately used for mathematical QA.
"""

import re


class FirstRow:
    """Presentation-following diagnostic policy, with uniform terminal forecasts."""

    def act(self, observation):
        row = re.search(r"Test ([0-2]):", observation)
        if row is None:
            raise ValueError("missing public test row")
        action = f"inspect {row.group(1)}"
        if observation.count("Remaining test budget: 0") != 0 or observation.count(f"'{action}'") != 0:
            return "answer 0 1/4 1/4 1/4 1/4"
        return action


class NeverInvestigate:
    def act(self, observation):
        return "answer 0 1/4 1/4 1/4 1/4"


class AlwaysDistrust:
    def act(self, observation):
        return "answer 1 1 1 0 1"


class StationarySource:
    """Always chooses the cheapest protocol, ignoring its effect on the sender."""

    def act(self, observation):
        if observation.count("Remaining queries=0") != 0:
            return "answer 1/2 1/2 1/4 1/4 1/2"
        return "protocol 0"

"""Four-state exact experiment calculus, shared by two distinct game mechanisms.

The trusted engine owns these objects. Agents receive rendered observations only.
No sampled hidden state participates in an ex ante action value.
"""

from fractions import Fraction


class Experiment:
    def __init__(self, a, b, c, d, cost="0"):
        self.a, self.b, self.c, self.d = Fraction(a), Fraction(b), Fraction(c), Fraction(d)
        self.cost = Fraction(cost)
        if min(self.a, self.b, self.c, self.d, self.cost) < 0:
            raise ValueError("negative probability or cost")
        if max(self.a, self.b, self.c, self.d, self.cost) > 1:
            raise ValueError("probability or cost exceeds one")

    def row(self):
        return (str(self.a), str(self.b), str(self.c), str(self.d), str(self.cost))


class Mass:
    def __init__(self, a, b, c, d):
        a, b, c, d = Fraction(a), Fraction(b), Fraction(c), Fraction(d)
        total = a + b + c + d
        if min(a, b, c, d) < 0 or total <= 0:
            raise ValueError("nonnegative mass with positive total required")
        self.a, self.b, self.c, self.d = a / total, b / total, c / total, d / total

    def row(self):
        return (str(self.a), str(self.b), str(self.c), str(self.d))

    def probability(self, experiment, outcome):
        if outcome == 1:
            return self.a * experiment.a + self.b * experiment.b + self.c * experiment.c + self.d * experiment.d
        if outcome == 0:
            return 1 - self.probability(experiment, 1)
        raise ValueError("outcome must be zero or one")

    def observe(self, experiment, outcome):
        if outcome == 1:
            return Mass(self.a * experiment.a, self.b * experiment.b, self.c * experiment.c, self.d * experiment.d)
        if outcome == 0:
            return Mass(self.a * (1 - experiment.a), self.b * (1 - experiment.b), self.c * (1 - experiment.c), self.d * (1 - experiment.d))
        raise ValueError("outcome must be zero or one")

    def risk(self, objective="world"):
        if objective == "world":
            return 1 - max(self.a, self.b, self.c, self.d)
        if objective == "sender":
            return min(self.a + self.b, self.c + self.d)
        raise ValueError("unknown decision objective")


class InquiryPlan:
    """Finite-horizon Bayes risk, including the option to stop and all test costs."""

    def __init__(self, first, second, third):
        self.experiments = (first, second, third)

    def branch(self, mass, experiment, outcome, remaining, used):
        weight = mass.probability(experiment, outcome)
        if weight == 0:
            return Fraction(0)
        return weight * self.value(mass.observe(experiment, outcome), remaining, used)

    def action_value(self, mass, remaining, used, action):
        if action == 3:
            return mass.risk()
        if action < 0 or action > 2:
            raise ValueError("unknown test")
        if remaining <= 0 or used & (1 << action):
            return Fraction(10)
        experiment = self.experiments[action]
        next_used = used | (1 << action)
        return experiment.cost + self.branch(mass, experiment, 0, remaining - 1, next_used) + self.branch(mass, experiment, 1, remaining - 1, next_used)

    def values(self, mass, remaining, used):
        if remaining < 0 or remaining > 3 or used < 0 or used > 7:
            raise ValueError("invalid finite inquiry state")
        return (self.action_value(mass, remaining, used, 0), self.action_value(mass, remaining, used, 1), self.action_value(mass, remaining, used, 2), mass.risk())

    def value(self, mass, remaining, used):
        return min(self.values(mass, remaining, used))

    def choose(self, mass, remaining, used):
        values = self.values(mass, remaining, used)
        # Prefer stopping on a tie; extra observations are not free evidence of skill.
        if values[3] == min(values):
            return 3
        return values.index(min(values))

"""Constrained two-role presentation trial, separate from private-type deployment."""

from .reference import PublicOracle
from .session import Session
from .trial import Trial


class FirstRowPresenter:
    """Construct a permutation against the declared first-row target model.

The objective is first-query regret, not realized hidden-world accuracy.
This is a positive control for a specified opponent, not a learned attacker.
"""

    def __init__(self, goal="adversarial"):
        if goal != "adversarial" and goal != "helpful":
            raise ValueError("unknown presenter goal")
        self.goal = goal

    def act(self, public_observation):
        oracle = PublicOracle()
        oracle.act(public_observation)
        costs = oracle.action_costs[:3]
        target = max(costs) if self.goal == "adversarial" else min(costs)
        action = costs.index(target)
        order = ((0, 1, 2), (1, 0, 2), (2, 0, 1))[action]
        return "present " + " ".join(map(str, order))


class TwoRoleTrial:
    def __init__(self, configuration, presenter, investigator):
        if not configuration.startswith("diagnostic "):
            raise ValueError("presentation trials require a diagnostic game")
        controller = Session()
        controller.start(configuration)
        # Only text crosses each role boundary; controller configuration is private.
        self.presentation = presenter.act(controller.game.presenter_view())
        self.trial = Trial(configuration, investigator, self.presentation)

    def run(self):
        return self.trial.run()

"""Independent observation-only solver using unnormalized decision-tree weights.

This implementation imports neither game engines nor their normalized probability
calculus. It reconstructs a decision problem from the text supplied to an agent.
It is a finite exhaustive baseline, not evidence against enumeration as a strategy.
"""

from fractions import Fraction
import re


class PublicOracle:
    def act(self, observation):
        self.observation = observation
        self.last_report = None
        self.used = 0
        if observation.startswith("Diagnose"):
            self.objective = "world"
            prior = re.search(r"Prior: \('([^']+)', '([^']+)', '([^']+)', '([^']+)'\)", observation)
            remaining = re.search(r"Remaining test budget: ([0-3])", observation)
            first = re.search(r"Test 0: \('([^']+)', '([^']+)', '([^']+)', '([^']+)', '([^']+)'\)", observation)
            second = re.search(r"Test 1: \('([^']+)', '([^']+)', '([^']+)', '([^']+)', '([^']+)'\)", observation)
            third = re.search(r"Test 2: \('([^']+)', '([^']+)', '([^']+)', '([^']+)', '([^']+)'\)", observation)
            if first is None or second is None or third is None:
                raise ValueError("missing diagnostic rows")
            self.rows = (tuple(map(Fraction, first.groups())), tuple(map(Fraction, second.groups())), tuple(map(Fraction, third.groups())))
        elif observation.startswith("Infer a persistent"):
            self.objective = "sender"
            prior = re.search(r"Prior joint weights .*?: \('([^']+)', '([^']+)', '([^']+)', '([^']+)'\)", observation)
            remaining = re.search(r"Remaining queries=([0-3])", observation)
            noise = re.search(r"independent error probability ([0-9/]+) each", observation)
            payoff = re.search(r"Acceptance gain=([0-9/]+);.*?fine=([0-9/]+)", observation)
            if noise is None or payoff is None:
                raise ValueError("missing source contract")
            error = Fraction(noise.group(1))
            gain, fine = tuple(map(Fraction, payoff.groups()))
            middle = 1 if gain > fine else 0
            high = 0
            if observation.count("Visibility=blind") != 0:
                middle, high = 1, 1
            self.rows = ((error, 1 - error, Fraction(1), Fraction(1), Fraction(1, 100)), (error, 1 - error, Fraction(middle), Fraction(1), Fraction(3, 100)), (error, 1 - error, Fraction(high), Fraction(1), Fraction(5, 100)))
        else:
            raise ValueError("unknown observation format")
        if prior is None or remaining is None:
            raise ValueError("missing prior or budget")
        weights = tuple(map(Fraction, prior.groups()))
        weights = self.history(weights, 0)
        remaining = int(remaining.group(1))
        costs = self.costs(weights, remaining, self.used)
        self.action_costs = costs
        if costs[3] != min(costs):
            action = costs.index(min(costs))
            return f"inspect {action}" if self.objective == "world" else f"protocol {action}"
        total = sum(weights)
        a, b, c, d = weights
        if self.objective == "world":
            return f"answer {weights.index(max(weights))} {a / total} {b / total} {c / total} {d / total}"
        intentional, error, falsehood = Fraction(0), Fraction(0), Fraction(0)
        if self.last_report == 1:
            intentional, error = c / total, a / total
            if observation.count("Report 1 states 'the final check passed'") != 0:
                falsehood = intentional + error
        return f"answer {(c + d) / total} {(a + c) / total} {intentional} {error} {falsehood}"

    def history(self, weights, offset):
        event = re.search(r"\('(inspect|protocol) ([0-2])', ([01])\)|\('reveal', ([01])\)", self.observation[offset:])
        if event is None:
            return weights
        action, index, outcome, reveal = event.groups()
        if reveal is not None:
            row = (Fraction(0), Fraction(1), Fraction(0), Fraction(1), Fraction(0))
            outcome = reveal
        else:
            row = self.rows[int(index)]
            if action == "inspect":
                self.used |= 1 << int(index)
            else:
                self.last_report = int(outcome)
        next_weights = self.condition(weights, row, int(outcome))
        return self.history(next_weights, offset + event.end())

    def condition(self, weights, row, outcome):
        a, b, c, d = weights
        if outcome == 1:
            return (a * row[0], b * row[1], c * row[2], d * row[3])
        return (a * (1 - row[0]), b * (1 - row[1]), c * (1 - row[2]), d * (1 - row[3]))

    def terminal(self, weights):
        a, b, c, d = weights
        if self.objective == "world":
            return sum(weights) - max(weights)
        return min(a + b, c + d)

    def cost(self, weights, remaining, used, action):
        if remaining == 0 or (self.objective == "world" and used & (1 << action)):
            return 10 * sum(weights)
        row = self.rows[action]
        next_used = used | (1 << action) if self.objective == "world" else used
        zero = self.condition(weights, row, 0)
        one = self.condition(weights, row, 1)
        return sum(weights) * row[4] + min(self.costs(zero, remaining - 1, next_used)) + min(self.costs(one, remaining - 1, next_used))

    def costs(self, weights, remaining, used):
        return (self.cost(weights, remaining, used, 0), self.cost(weights, remaining, used, 1), self.cost(weights, remaining, used, 2), self.terminal(weights))

"""Bounded text transport; no providers, credentials, shell, or subprocess access.

Run this transport only in an authorized isolated runner. The trusted process
retains latent state; an external agent receives view() text and submits lines.
"""

import json
import re
import sys

from .diagnostic import Diagnostic
from .strategic import Sender, StrategicSource


class Session:
    def __init__(self, source=None, sink=None):
        self.source = sys.stdin if source is None else source
        self.sink = sys.stdout if sink is None else sink
        self.game = None
        self.remaining_lines = 12

    def start(self, command):
        match = re.fullmatch(r"diagnostic ([0-9]{1,8}) ([0-9]{1,8}) ([1-3]) (balanced|skewed)", command)
        if match is not None:
            seed, world, budget, variant = match.groups()
            self.game = Diagnostic(int(seed), int(world), int(budget), variant)
            return self.game.presenter_view()
        match = re.fullmatch(r"source ([0-9]{1,8}) ([0-9]{1,8}) ([1-3]) (disclosed|blind) (assertion|certificate)", command)
        if match is not None:
            seed, world, budget, visibility, channel = match.groups()
            self.game = StrategicSource(int(seed), int(world), int(budget), visibility, channel)
            return self.game.view()
        raise ValueError("start: diagnostic SEED PRIVATE_WORLD_SEED BUDGET balanced|skewed; or source SEED PRIVATE_WORLD_SEED BUDGET disclosed|blind assertion|certificate")

    def run(self):
        if self.game is None:
            # Initialization is a controller-only input, not part of agent history.
            command = self.source.readline(512)
            if command == "":
                return
            try:
                self.sink.write(self.start(command.rstrip("\r\n")) + "\n")
            except ValueError as exc:
                self.sink.write(f"configuration_error: {exc}\n")
                return
        if self.remaining_lines == 0:
            self.sink.write("protocol_error: response limit reached; unscored\n")
            return
        self.sink.flush()
        raw = self.source.readline(512)
        if raw == "":
            self.sink.write("incomplete_episode: unscored\n")
            return
        self.remaining_lines -= 1
        raw = raw.rstrip("\r\n")
        try:
            if self.game.stage == "present":
                self.game.present(raw)
            else:
                self.game.step(raw)
        except ValueError as exc:
            self.sink.write(f"invalid_action: {exc}\n")
        if self.game.stage == "done":
            self.sink.write(json.dumps(("episode_result", self.game.result, ("actions_and_observations", self.game.trace))) + "\n")
            self.sink.flush()
            return
        self.sink.write(self.game.view() + "\n")
        return self.run()


class Replay:
    """Reconstruct from controller configuration and action strings, not claimed scores."""

    def __init__(self, configuration):
        self.session = Session()
        self.session.start(configuration)
        self.actions = 0

    def consume(self, transcript):
        if transcript == ():
            if self.session.game.stage != "done":
                raise ValueError("incomplete replay")
            return (self.session.game.trace, self.session.game.result)
        if self.actions >= 6:
            raise ValueError("too many replay actions")
        raw = transcript[0]
        if self.session.game.stage == "present":
            self.session.game.present(raw)
        else:
            self.session.game.step(raw)
        self.actions += 1
        return self.consume(transcript[1:])


class SenderSession:
    """One-action deployment port; quality is this agent's permitted private information."""

    def __init__(self, quality, gain, fine, rate, channel):
        self.game = Sender(quality, gain, fine, rate, channel)

    def run(self, source, sink):
        sink.write(self.game.view())
        sink.flush()
        raw = source.readline(512).rstrip("\r\n")
        try:
            sink.write(json.dumps(("sender_result", self.game.grade(raw))) + "\n")
        except ValueError as exc:
            sink.write(f"invalid_action: {exc}; unscored\n")

"""Audit-conditioned communication, truthful selection, and uncertain attribution.

Source: dialogue lines 65–99, 164–168, 1187–1208, 3178–3219, 3574–3658.
The four states are (sincere,bad), (sincere,good), (strategic,bad),
(strategic,good). The same report can arise from error or strategy. Scoring
requires calibrated observable predictions, never guessing a hidden cause label.
"""

from fractions import Fraction
from hashlib import sha256
from random import Random
import re

from .finite import Experiment, Mass


class Sender:
    """A decision maker with private quality and an explicit audit contract."""

    def __init__(self, quality, gain, fine, rate, channel="assertion"):
        if str(quality) != "0" and str(quality) != "1":
            raise ValueError("quality must be 0 or 1")
        self.quality = int(quality)
        self.gain, self.fine, self.rate = Fraction(gain), Fraction(fine), Fraction(rate)
        if min(self.gain, self.fine) <= 0 or self.rate < 0 or self.rate > 1:
            raise ValueError("invalid payoff contract")
        if channel != "assertion" and channel != "certificate":
            raise ValueError("unknown communication channel")
        self.channel = channel

    def utility(self, report):
        if report == 0:
            return Fraction(0)
        if report != 1:
            raise ValueError("report must be 0 or 1")
        if self.quality == 1:
            return self.gain
        return (1 - self.rate) * self.gain - self.rate * self.fine

    def best(self):
        if self.utility(1) > 0:
            return 1
        return 0

    def view(self):
        positive = "the final check passed" if self.channel == "assertion" else "the precheck passed"
        return (f"You know final quality={self.quality}; the precheck passed in every case.\n"
                f"Report 1 states '{positive}' and recommends acceptance. Report 0 declines to recommend.\n"
                f"Acceptance pays {self.gain}. Auditing occurs with probability {self.rate}; a bad final check cancels acceptance and costs {self.fine}.\n"
                "Report 0 pays zero. The audit contract applies to misleading omissions as well as false claims. Choose report 0 or report 1.\n")

    def grade(self, raw):
        match = re.fullmatch(r"report ([01])", raw)
        if match is None:
            raise ValueError("invalid sender action")
        report = int(match.group(1))
        utility = self.utility(report)
        return (("deployment_regret", str(max(self.utility(0), self.utility(1)) - utility)), ("expected_utility", str(utility)), ("channel", self.channel))


class SourcePlan:
    """Adaptive finite-horizon inference about a persistent sender, with repeatable probes."""

    def __init__(self, first, second, third):
        self.experiments = (first, second, third)

    def branch(self, mass, experiment, outcome, remaining):
        weight = mass.probability(experiment, outcome)
        if weight == 0:
            return Fraction(0)
        return weight * self.value(mass.observe(experiment, outcome), remaining)

    def action_value(self, mass, remaining, action):
        if action == 3:
            return mass.risk("sender")
        if action < 0 or action > 2:
            raise ValueError("unknown protocol")
        if remaining == 0:
            return Fraction(10)
        experiment = self.experiments[action]
        return experiment.cost + self.branch(mass, experiment, 0, remaining - 1) + self.branch(mass, experiment, 1, remaining - 1)

    def values(self, mass, remaining):
        if remaining < 0 or remaining > 3:
            raise ValueError("invalid inquiry horizon")
        return (self.action_value(mass, remaining, 0), self.action_value(mass, remaining, 1), self.action_value(mass, remaining, 2), mass.risk("sender"))

    def value(self, mass, remaining):
        return min(self.values(mass, remaining))

    def choose(self, mass, remaining):
        values = self.values(mass, remaining)
        if values[3] == min(values):
            return 3
        return values.index(min(values))


class StrategicSource:
    def __init__(self, semantic_seed=0, world_seed=0, budget=2, visibility="disclosed", channel="assertion", noise="1/4"):
        if re.fullmatch(r"[0-9]{1,8}", str(semantic_seed)) is None or re.fullmatch(r"[0-9]{1,8}", str(world_seed)) is None:
            raise ValueError("unsigned seed below 100000000 required")
        if str(budget) != "1" and str(budget) != "2" and str(budget) != "3":
            raise ValueError("budget must be 1, 2, or 3")
        semantic_seed, world_seed, budget = int(semantic_seed), int(world_seed), int(budget)
        if visibility != "disclosed" and visibility != "blind":
            raise ValueError("unknown visibility")
        if channel != "assertion" and channel != "certificate":
            raise ValueError("unknown channel")
        self.noise = Fraction(noise)
        if self.noise < 0 or self.noise >= Fraction(1, 2) or self.noise.denominator > 8:
            raise ValueError("noise must be in [0,1/2) with denominator at most 8")
        self.gain = Fraction(2 + semantic_seed % 3)
        self.fine = Fraction(1 + (semantic_seed // 3) % 5)
        self.rates = (Fraction(0), Fraction(1, 2), Fraction(1))
        prior_good = Fraction(2 + semantic_seed % 3, 6)
        prior_strategic = Fraction(2 + (semantic_seed // 3) % 3, 6)
        self.mass = Mass((1 - prior_good) * (1 - prior_strategic), prior_good * (1 - prior_strategic), (1 - prior_good) * prior_strategic, prior_good * prior_strategic)
        self.initial = self.mass
        self.semantic_seed, self.world_seed = semantic_seed, world_seed
        self.budget, self.remaining, self.round = budget, budget, 0
        self.visibility, self.channel = visibility, channel
        rate1, rate2 = Fraction(1, 2), Fraction(1)
        if visibility == "blind":
            rate1, rate2 = Fraction(0), Fraction(0)
        first = Experiment(self.noise, 1 - self.noise, Sender(0, self.gain, self.fine, 0).best(), 1, "1/100")
        second = Experiment(self.noise, 1 - self.noise, Sender(0, self.gain, self.fine, rate1).best(), 1, "3/100")
        third = Experiment(self.noise, 1 - self.noise, Sender(0, self.gain, self.fine, rate2).best(), 1, "5/100")
        self.plan = SourcePlan(first, second, third)
        self.quality = 1 if Random(f"source-quality-v1:{world_seed}").randrange(prior_good.denominator) < prior_good.numerator else 0
        self.kind = 1 if Random(f"source-kind-v1:{world_seed}").randrange(prior_strategic.denominator) < prior_strategic.numerator else 0
        self.trace, self.regrets = (), ()
        self.cost = Fraction(0)
        self.stage, self.last_report = "inquire", None
        self.result = None
        canonical = ("strategic-source-v1", self.mass.row(), str(self.gain), str(self.fine), str(self.noise), budget, visibility, channel)
        self.semantic_id = sha256(repr(canonical).encode("utf8")).hexdigest()

    def view(self):
        statement = "the final check passed" if self.channel == "assertion" else "the precheck passed"
        return ("Infer a persistent source's disposition and final quality. Minimize disposition-classification error plus protocol costs.\n"
                f"Prior joint weights (sincere/bad, sincere/good, strategic/bad, strategic/good): {self.initial.row()}.\n"
                f"A sincere source observes a fresh private signal with independent error probability {self.noise} each round and reports that signal.\n"
                "A strategic source knows final quality and maximizes expected sender payoff. Ties choose report 0.\n"
                f"Report 1 states '{statement}' and recommends acceptance; report 0 declines. The precheck passed in all worlds.\n"
                f"Acceptance gain={self.gain}; a bad final check discovered at audit cancels acceptance and costs fine={self.fine}. Report 0 earns zero.\n"
                f"Protocols 0,1,2 set audit probabilities 0,1/2,1, at query costs 1/100,3/100,5/100. Visibility={self.visibility}.\n"
                "Under disclosed protocols the sender sees the actual audit probability. Under blind protocols the sender always believes it is zero.\n"
                "Audits settle the contract outside this observation channel; only the report is observed here. The sender does not learn audit outcomes between rounds.\n"
                f"Remaining queries={self.remaining}; history={self.trace!r}. Repeating a protocol is legal.\n"
                "Actions: protocol ID; reveal; answer p_strategic p_bad p_intentional p_error p_literal_false. Use exact fractions in [0,1].\n"
                "Your disposition decision is strategic when p_strategic is at least 1/2, otherwise sincere. Classification loss, query cost, and forecast scores are reported separately.\n"
                "Intentional/error events concern the latest positive recommendation on bad quality. Before any report both events are absent.\n"
                "Literal falsehood concerns the latest statement; report 0 makes no quality assertion. A precheck certificate is always literally true.\n"
                "An optional independent reveal supplies final quality after at least one report; it is a separately flagged recovery intervention, outside the inquiry objective.\n")

    def event_probabilities(self):
        intentional, error, falsehood = Fraction(0), Fraction(0), Fraction(0)
        if self.last_report == 1:
            intentional, error = self.mass.c, self.mass.a
            if self.channel == "assertion":
                falsehood = intentional + error
        return (self.mass.c + self.mass.d, self.mass.a + self.mass.c, intentional, error, falsehood)

    def step(self, raw):
        if self.stage != "inquire":
            raise ValueError("episode closed")
        match = re.fullmatch(r"protocol ([0-2])", raw)
        if match is not None:
            if self.remaining == 0:
                raise ValueError("query budget exhausted")
            action = int(match.group(1))
            experiment = self.plan.experiments[action]
            regret = self.plan.action_value(self.mass, self.remaining, action) - self.plan.value(self.mass, self.remaining)
            index = 2 * self.kind + self.quality
            likelihood = (experiment.a, experiment.b, experiment.c, experiment.d)[index]
            draw = Random(f"source-report-v1:{self.world_seed}:{self.round}").randrange(likelihood.denominator)
            report = 1 if draw < likelihood.numerator else 0
            next_mass = self.mass.observe(experiment, report)
            self.mass, self.last_report = next_mass, report
            self.remaining -= 1
            self.round += 1
            self.regrets += (regret,)
            self.cost += experiment.cost
            self.trace += ((raw, report),)
            return f"report {report}"
        if raw == "reveal":
            if self.round == 0 or self.trace.count(("reveal", self.quality)) != 0:
                raise ValueError("reveal requires a report and may occur once")
            self.mass = self.mass.observe(Experiment(0, 1, 0, 1), self.quality)
            self.trace += (("reveal", self.quality),)
            return f"independent final quality {self.quality}"
        match = re.fullmatch(r"answer ([0-9]{1,6}(?:/[1-9][0-9]{0,5})?) ([0-9]{1,6}(?:/[1-9][0-9]{0,5})?) ([0-9]{1,6}(?:/[1-9][0-9]{0,5})?) ([0-9]{1,6}(?:/[1-9][0-9]{0,5})?) ([0-9]{1,6}(?:/[1-9][0-9]{0,5})?)", raw)
        if match is None:
            raise ValueError("invalid action grammar")
        p, q, i, e, f = tuple(map(Fraction, match.groups()))
        if min(p, q, i, e, f) < 0 or max(p, q, i, e, f) > 1:
            raise ValueError("forecast outside [0,1]")
        target_p, target_q, target_i, target_e, target_f = self.event_probabilities()
        intentional, error, falsehood = 0, 0, 0
        if self.last_report == 1 and self.quality == 0:
            intentional, error = self.kind, 1 - self.kind
            if self.channel == "assertion":
                falsehood = 1
        decision = 1 if p >= Fraction(1, 2) else 0
        decision_loss = 0 if decision == self.kind else 1
        decision_risk = 1 - target_p if decision == 1 else target_p
        excess = (
            (p - target_p) ** 2,
            (q - target_q) ** 2,
            (i - target_i) ** 2,
            (e - target_e) ** 2,
            (f - target_f) ** 2,
        )
        stop_regret = self.mass.risk("sender") - self.plan.value(self.mass, self.remaining)
        self.result = (
            ("disposition_brier", str((p - self.kind) ** 2)),
            ("quality_brier", str((q - (1 - self.quality)) ** 2)),
            ("intent_brier", str((i - intentional) ** 2)),
            ("error_brier", str((e - error) ** 2)),
            ("literal_falsehood_brier", str((f - falsehood) ** 2)),
            ("forecast_excess", tuple(map(str, excess))),
            ("protocol_regrets", tuple(map(str, self.regrets))),
            ("stop_regret", str(stop_regret)),
            ("recovery_arm", str(self.trace.count(("reveal", self.quality)))),
            ("disposition_decision_loss", str(decision_loss)),
            ("disposition_decision_regret", str(decision_risk - self.mass.risk("sender"))),
            ("protocol_cost", str(self.cost)),
        )
        self.trace += (raw,)
        self.stage = "done"
        return self.result

    def reference_action(self):
        action = self.plan.choose(self.mass, self.remaining)
        if action != 3:
            return f"protocol {action}"
        return "answer " + " ".join(map(str, self.event_probabilities()))

"""Provider-free, bounded trials for trusted scripted policies and isolated readiness runs."""

from .session import Session


class Trial:
    def __init__(self, configuration, policy, presentation="present 0 1 2"):
        self.controller = Session()
        self.controller.start(configuration)
        self.policy = policy
        self.configuration = configuration
        self.actions = ()
        self.invalid = ()
        self.events = ()
        self.remaining_calls = 12
        self.status = "open"
        if self.controller.game.stage == "present":
            self.controller.game.present(presentation)
            self.actions += (presentation,)

    def run(self):
        game = self.controller.game
        if game.stage == "done":
            self.status = "scored"
            return self.record()
        if self.remaining_calls == 0:
            self.status = "invalid_response_limit_unscored"
            return self.record()
        self.remaining_calls -= 1
        observation = game.view()
        raw = self.policy.act(observation)
        self.events += (("observation", observation), ("response", raw))
        try:
            result = game.step(raw)
        except ValueError as exc:
            self.invalid += ((raw, str(exc)),)
            self.events += (("invalid_action", str(exc)),)
        else:
            self.actions += (raw,)
            self.events += (("transition", result),)
        return self.run()

    def record(self):
        # Controller artifact: never use this as an agent observation.
        return (("schema", "inquiry-trial/1"), ("configuration", self.configuration), ("status", self.status), ("actions", self.actions), ("invalid_responses", self.invalid), ("events", self.events), ("engine_trace", self.controller.game.trace), ("metrics", self.controller.game.result))

"""Infer hidden local rules, evaluate nested programs, and submit a transferable model."""

from fractions import Fraction
from hashlib import sha256
from random import Random
import re

from .semantics import Posterior, Rule, TreeFactory


class ProgramDiscovery:
    def __init__(self, semantic_seed=0, world_seed=0, depth=3, operators=2, width=2, budget=6, shape="balanced", sharing="distinct", demonstrations=0, modulus=7):
        if re.fullmatch(r"[0-9]{1,8}", str(semantic_seed)) is None or re.fullmatch(r"[0-9]{1,8}", str(world_seed)) is None:
            raise ValueError("unsigned seeds below 100000000 required")
        if re.fullmatch(r"[2-5]", str(depth)) is None or re.fullmatch(r"[1-3]", str(operators)) is None:
            raise ValueError("depth 2..5 and operator count 1..3 required")
        if re.fullmatch(r"[23]", str(width)) is None or re.fullmatch(r"[0-9]", str(budget)) is None:
            raise ValueError("width 2 or 3 and query budget 0..9 required")
        if re.fullmatch(r"[0-2]", str(demonstrations)) is None or (str(modulus) != "7" and str(modulus) != "11"):
            raise ValueError("demonstrations 0..2 and modulus 7 or 11 required")
        if shape != "chain" and shape != "balanced":
            raise ValueError("unknown tree shape")
        if sharing != "distinct" and sharing != "repeated":
            raise ValueError("unknown subtree condition")
        if sharing == "repeated" and shape != "balanced":
            raise ValueError("repeated subtrees require balanced branching")
        semantic_seed, world_seed = int(semantic_seed), int(world_seed)
        self.depth, self.operators, self.width = int(depth), int(operators), int(width)
        self.remaining, self.budget = int(budget), int(budget)
        self.demonstrations, self.modulus = int(demonstrations), int(modulus)
        self.shape, self.sharing = shape, sharing
        self.stage, self.result, self.spent = "open", None, 0
        self.actions, self.observations = (), ()
        public = TreeFactory(f"recursive-public-v1:{semantic_seed}", self.operators, self.modulus)
        private = TreeFactory(f"recursive-transfer-v1:{semantic_seed}", self.operators, self.modulus)
        labels = ("A", "B", "C")
        self.targets = (public.make(self.depth, shape, sharing, labels[0]), public.make(self.depth, shape, sharing, labels[1 % self.operators]), public.make(self.depth, shape, sharing, labels[2 % self.operators]))
        self.transfer = (private.make(self.depth + 1, shape, sharing, labels[0]), private.make(self.depth + 1, shape, sharing, labels[1 % self.operators]), private.make(self.depth + 1, shape, sharing, labels[2 % self.operators]))
        secret = Random(f"recursive-rule-v1:{world_seed}")
        self.rules = self.draw_rules(secret, 0)
        self.demonstrate(0, 0)
        canonical = ("recursive-programs/1", self.depth, self.operators, self.width, self.budget, shape, sharing, self.demonstrations, self.modulus, self.targets[0].render(), self.targets[1].render(), self.targets[2].render())
        self.semantic_id = sha256(repr(canonical).encode("utf8")).hexdigest()

    def draw_rules(self, rng, position):
        if position == 3:
            return ()
        if position >= self.operators:
            rule = Rule(1, 1, 0)
        else:
            rule = Rule(rng.randrange(1, self.width + 1), rng.randrange(1, self.width + 1), rng.randrange(self.width))
        return (rule,) + self.draw_rules(rng, position + 1)

    def demonstrate(self, operator, basis):
        if operator == self.operators:
            return
        if basis == self.demonstrations:
            return self.demonstrate(operator + 1, 0)
        left, right = ((0, 0), (1, 0), (0, 1))[basis]
        label = ("A", "B", "C")[operator]
        outcome = self.rules[operator].apply(left, right, self.modulus)
        self.observations += ((label, left, right, outcome),)
        return self.demonstrate(operator, basis + 1)

    def observation_text(self, observations):
        if observations == ():
            return ""
        label, left, right, value = observations[0]
        return f"Observation {label} {left} {right} = {value}\n" + self.observation_text(observations[1:])

    def view(self):
        labels = "ABC"[:self.operators]
        return ("Recursive rule discovery. Infer local operator rules and predict nested programs.\n"
                f"Modulus={self.modulus}; Operators={self.operators}; Width={self.width}; Remaining={self.remaining}.\n"
                f"Active labels={labels}. Each label has a fixed hidden rule (a*left+b*right+c) modulo the modulus.\n"
                f"Independently for each label, a and b are uniform integers 1..{self.width}; c is uniform 0..{self.width - 1}.\n"
                "Every leaf is a literal residue. The same local rule applies at every nesting level.\n"
                f"Target 0: {self.targets[0].render()}\nTarget 1: {self.targets[1].render()}\nTarget 2: {self.targets[2].render()}\n"
                + self.observation_text(self.observations)
                + "Actions: probe LABEL LEFT RIGHT, with literal residues only; no nested probes or repeated inputs.\n"
                "Finish: answer V0 V1 V2 model aA bA cA [aB bB cB] [aC bC cC], with exactly one coefficient triple per active label.\n"
                "Predictions and the submitted model are scored separately. A model can remain uncertain under insufficient evidence.\n"
                "Your model is also evaluated on three unseen programs one level deeper; those programs cannot be probed.\n")

    def has_probe(self, label, left, right, observations):
        if observations == ():
            return 0
        old_label, old_left, old_right, outcome = observations[0]
        if label == old_label and left == old_left and right == old_right:
            return 1
        return self.has_probe(label, left, right, observations[1:])

    def parse_rules(self, coefficients, position=0):
        if position == 3:
            return ()
        if position >= self.operators:
            return (Rule(1, 1, 0),) + self.parse_rules(coefficients, position + 1)
        a, b, c = tuple(map(int, coefficients[3 * position:3 * position + 3]))
        if min(a, b) < 1 or max(a, b) > self.width or c < 0 or c >= self.width:
            raise ValueError("model coefficients outside the declared family")
        return (Rule(a, b, c),) + self.parse_rules(coefficients, position + 1)

    def consistent(self, rules, observations):
        if observations == ():
            return 1
        label, left, right, outcome = observations[0]
        if rules[("A", "B", "C").index(label)].apply(left, right, self.modulus) != outcome:
            return 0
        return self.consistent(rules, observations[1:])

    def errors(self, predictions, targets, rules, position=0):
        if position == 3:
            return 0
        error = 0 if predictions[position] == targets[position].reduce(rules, self.modulus) else 1
        return error + self.errors(predictions, targets, rules, position + 1)

    def nonassociative_operators(self, position=0):
        if position == self.operators:
            return 0
        rule = self.rules[position]
        count = 1 if rule.a != 1 or rule.b != 1 else 0
        return count + self.nonassociative_operators(position + 1)

    def step(self, raw):
        if self.stage != "open":
            raise ValueError("episode closed")
        probe = re.fullmatch(r"probe ([ABC]) ([0-9]{1,2}) ([0-9]{1,2})", raw)
        if probe is not None:
            label, left, right = probe.groups()
            operator, left, right = ("A", "B", "C").index(label), int(left), int(right)
            if operator >= self.operators or max(left, right) >= self.modulus:
                raise ValueError("inactive label or invalid residue")
            if self.remaining == 0 or self.has_probe(label, left, right, self.observations) == 1:
                raise ValueError("query budget exhausted or repeated input")
            outcome = self.rules[operator].apply(left, right, self.modulus)
            self.observations += ((label, left, right, outcome),)
            self.actions += (raw,)
            self.remaining -= 1
            self.spent += 1
            return f"Observation {label} {left} {right} = {outcome}"
        answer = re.fullmatch(r"answer ([0-9]{1,2}) ([0-9]{1,2}) ([0-9]{1,2}) model" + r" ([1-3]) ([1-3]) ([0-2])" * self.operators, raw)
        if answer is None:
            raise ValueError("invalid answer grammar")
        values = tuple(map(int, answer.groups()[:3]))
        if max(values) >= self.modulus:
            raise ValueError("prediction outside the residue space")
        model = self.parse_rules(answer.groups()[3:])
        posterior = Posterior(self.operators, self.width, self.modulus, self.observations, self.targets + self.transfer)
        expected, risk = posterior.losses(values)
        transfer_values = (self.transfer[0].reduce(model, self.modulus), self.transfer[1].reduce(model, self.modulus), self.transfer[2].reduce(model, self.modulus))
        transfer_expected, transfer_risk = posterior.losses(transfer_values, 3)
        self.result = (
            ("prediction_loss", str(Fraction(self.errors(values, self.targets, self.rules), 3))),
            ("prediction_expected_loss", str(expected / 3)),
            ("prediction_bayes_risk", str(risk / 3)),
            ("prediction_regret", str((expected - risk) / 3)),
            ("certificate_consistent", str(self.consistent(model, self.observations))),
            ("candidate_grammars", str(posterior.total)),
            ("identified_from_evidence", str(1 if posterior.total == 1 else 0)),
            ("composition_errors_given_certificate", str(self.errors(values, self.targets, model))),
            ("certificate_transfer_loss", str(Fraction(self.errors(transfer_values, self.transfer, self.rules), 3))),
            ("certificate_transfer_excess_vs_marginal_oracle", str((transfer_expected - transfer_risk) / 3)),
            ("queries", str(self.spent)),
            ("public_depth", str(self.depth)),
            ("public_node_counts", (self.targets[0].nodes, self.targets[1].nodes, self.targets[2].nodes)),
            ("public_distinct_subtrees", (self.targets[0].distinct_subtrees(), self.targets[1].distinct_subtrees(), self.targets[2].distinct_subtrees())),
            ("nonassociative_operators", str(self.nonassociative_operators())),
        )
        self.actions += (raw,)
        self.stage = "done"
        return self.result

"""Public-text reference using path-weighted expansion, without engine imports.

The probe policy completes an identifying affine basis. It is not claimed to
minimize the number of probes. Terminal predictions are posterior modes over
all models consistent with the public local observations.
"""

import re


class Choices:
    def __init__(self, label, width, modulus, observation, active=1):
        self.label, self.width, self.modulus = label, width, modulus
        self.observation, self.entries = observation, ()
        if active == 0:
            self.entries = ((1, 1, 0),)
        else:
            self.search(1, 1, 0)
        if self.entries == ():
            raise ValueError("public evidence has no compatible rule")

    def compatible(self, coefficients, offset=0):
        event = re.search(r"^Observation " + self.label + r" ([0-9]{1,2}) ([0-9]{1,2}) = ([0-9]{1,2})$", self.observation[offset:], re.MULTILINE)
        if event is None:
            return 1
        x, y, observed = tuple(map(int, event.groups()))
        a, b, c = coefficients
        if (a * x + b * y + c) % self.modulus != observed:
            return 0
        return self.compatible(coefficients, offset + event.end())

    def search(self, a, b, c):
        if a > self.width:
            return
        if b > self.width:
            return self.search(a + 1, 1, 0)
        if c == self.width:
            return self.search(a, b + 1, 0)
        if self.compatible((a, b, c)) == 1:
            self.entries += ((a, b, c),)
        return self.search(a, b, c + 1)


class PublicSolver:
    def __init__(self, mode="full"):
        if mode != "full" and mode != "shallow":
            raise ValueError("unknown composition policy")
        self.mode = mode

    def missing_basis(self, position=0, basis=0):
        if position == self.operators:
            return None
        if basis == 3:
            return self.missing_basis(position + 1, 0)
        label = "ABC"[position]
        left, right = ((0, 0), (1, 0), (0, 1))[basis]
        if re.search(r"^Observation " + label + f" {left} {right} = [0-9]+$", self.observation, re.MULTILINE) is None:
            return f"probe {label} {left} {right}"
        return self.missing_basis(position, basis + 1)

    def evaluate(self, program, rules, modulus):
        self.program, self.rules, self.modulus = program, rules, modulus
        self.parse_nodes = 0
        end, contribution, first_leaf = self.expand(0, 1, 0)
        if program[end:] != "":
            raise ValueError("trailing expression text")
        return contribution % modulus

    def expand(self, position, weight, depth):
        self.parse_nodes += 1
        if depth > 6 or self.parse_nodes > 255:
            raise ValueError("expression exceeds reference bounds")
        literal = re.match(r"[0-9]{1,2}", self.program[position:])
        if literal is not None:
            value = int(literal.group(0))
            if value >= self.modulus:
                raise ValueError("invalid leaf residue")
            return (position + literal.end(), weight * value, value)
        label = self.program[position:position + 1]
        if label != "A" and label != "B" and label != "C":
            raise ValueError("unknown operator")
        if self.program[position + 1:position + 2] != "(":
            raise ValueError("missing opening delimiter")
        a, b, c = self.rules["ABC".index(label)]
        end_left, left, first_leaf = self.expand(position + 2, weight * a, depth + 1)
        if self.program[end_left:end_left + 1] != ",":
            raise ValueError("missing child delimiter")
        end_right, right, other_leaf = self.expand(end_left + 1, weight * b, depth + 1)
        if self.program[end_right:end_right + 1] != ")":
            raise ValueError("missing closing delimiter")
        if self.mode == "shallow" and depth > 0:
            return (end_right + 1, weight * first_leaf, first_leaf)
        return (end_right + 1, weight * c + left + right, first_leaf)

    def enumerate_models(self, position, chosen):
        if position == 3:
            return self.accumulate(chosen, 0)
        return self.enumerate_choices(position, chosen, self.choices[position].entries)

    def enumerate_choices(self, position, chosen, candidates):
        if candidates == ():
            return
        self.enumerate_models(position + 1, chosen + (candidates[0],))
        return self.enumerate_choices(position, chosen, candidates[1:])

    def accumulate(self, rules, position):
        if position == 3:
            return
        value = self.evaluate(self.targets[position], rules, self.modulus)
        counts = self.counts[position]
        counts = counts[:value] + (counts[value] + 1,) + counts[value + 1:]
        self.counts = self.counts[:position] + (counts,) + self.counts[position + 1:]
        return self.accumulate(rules, position + 1)

    def certificate(self, position=0):
        if position == self.operators:
            return ()
        return self.choices[position].entries[0] + self.certificate(position + 1)

    def act(self, observation):
        self.observation = observation
        header = re.search(r"Modulus=(7|11); Operators=([1-3]); Width=([23]); Remaining=([0-9])\.", observation)
        if header is None:
            raise ValueError("missing public recursive-program contract")
        self.modulus, self.operators, self.width, remaining = tuple(map(int, header.groups()))
        query = self.missing_basis()
        if remaining > 0 and query is not None:
            return query
        first = re.search(r"^Target 0: ([ABC0-9(),]+)$", observation, re.MULTILINE)
        second = re.search(r"^Target 1: ([ABC0-9(),]+)$", observation, re.MULTILINE)
        third = re.search(r"^Target 2: ([ABC0-9(),]+)$", observation, re.MULTILINE)
        if first is None or second is None or third is None:
            raise ValueError("missing public targets")
        self.targets = (first.group(1), second.group(1), third.group(1))
        self.choices = (
            Choices("A", self.width, self.modulus, observation),
            Choices("B", self.width, self.modulus, observation, 1 if self.operators >= 2 else 0),
            Choices("C", self.width, self.modulus, observation, 1 if self.operators >= 3 else 0),
        )
        self.counts = ((0,) * self.modulus, (0,) * self.modulus, (0,) * self.modulus)
        self.enumerate_models(0, ())
        a, b, c = self.counts
        return f"answer {a.index(max(a))} {b.index(max(b))} {c.index(max(c))} model " + " ".join(map(str, self.certificate()))


class ShallowSolver(PublicSolver):
    """Learns local rules, then collapses each internal child to its first leaf."""

    def __init__(self):
        super().__init__("shallow")


class ZeroSolver:
    def act(self, observation):
        count = re.search(r"Operators=([1-3]);", observation)
        if count is None:
            raise ValueError("missing operator count")
        return "answer 0 0 0 model" + " 1 1 0" * int(count.group(1))

"""Trusted recursive reduction and exact finite model accounting."""

from fractions import Fraction
from random import Random


class Rule:
    def __init__(self, a, b, c):
        self.a, self.b, self.c = a, b, c

    def apply(self, left, right, modulus):
        return (self.a * left + self.b * right + self.c) % modulus

    def coefficients(self):
        return (self.a, self.b, self.c)


class Node:
    def __init__(self, label, left=None, right=None, value=0):
        self.label, self.left, self.right, self.value = label, left, right, value
        if label == "leaf":
            self.depth, self.nodes = 0, 1
        else:
            self.depth = 1 + max(left.depth, right.depth)
            self.nodes = 1 + left.nodes + right.nodes

    def reduce(self, rules, modulus):
        if self.label == "leaf":
            return self.value
        index = ("A", "B", "C").index(self.label)
        return rules[index].apply(self.left.reduce(rules, modulus), self.right.reduce(rules, modulus), modulus)

    def render(self):
        if self.label == "leaf":
            return str(self.value)
        return f"{self.label}({self.left.render()},{self.right.render()})"

    def signatures(self):
        if self.label == "leaf":
            return (self.render(),)
        return (self.render(),) + self.left.signatures() + self.right.signatures()

    def distinct_subtrees(self, remaining=None, seen=()):
        if remaining is None:
            remaining = self.signatures()
        if remaining == ():
            return 0
        head, tail = remaining[0], remaining[1:]
        if seen.count(head) != 0:
            return self.distinct_subtrees(tail, seen)
        return 1 + self.distinct_subtrees(tail, seen + (head,))


class TreeFactory:
    def __init__(self, seed, operators, modulus):
        self.rng = Random(seed)
        self.operators, self.modulus = operators, modulus

    def make(self, depth, shape, sharing, root_label=None):
        if depth == 0:
            return Node("leaf", value=self.rng.randrange(self.modulus))
        label = ("A", "B", "C")[self.rng.randrange(self.operators)] if root_label is None else root_label
        if shape == "chain":
            child = self.make(depth - 1, shape, sharing)
            leaf = self.make(0, shape, sharing)
            if self.rng.randrange(2) == 0:
                return Node(label, child, leaf)
            return Node(label, leaf, child)
        left = self.make(depth - 1, shape, sharing)
        right = left if sharing == "repeated" else self.make(depth - 1, shape, sharing)
        return Node(label, left, right)


class RulePool:
    def __init__(self, operator, width, modulus, observations, active=1):
        self.operator, self.width, self.modulus = operator, width, modulus
        self.observations = observations
        self.entries, self.count = (), 0
        if active == 0:
            self.entries, self.count = (Rule(1, 1, 0),), 1
        else:
            self.scan(1, 1, 0)
        if self.count == 0:
            raise ValueError("observations contradict the declared rule family")

    def agrees(self, rule, observations):
        if observations == ():
            return 1
        operator, left, right, outcome = observations[0]
        if operator == self.operator and rule.apply(left, right, self.modulus) != outcome:
            return 0
        return self.agrees(rule, observations[1:])

    def scan(self, a, b, c):
        if a > self.width:
            return
        if b > self.width:
            return self.scan(a + 1, 1, 0)
        if c == self.width:
            return self.scan(a, b + 1, 0)
        candidate = Rule(a, b, c)
        if self.agrees(candidate, self.observations) == 1:
            self.entries += (candidate,)
            self.count += 1
        return self.scan(a, b, c + 1)


class Histogram:
    def __init__(self, modulus):
        self.counts = (0,) * modulus

    def add(self, value):
        self.counts = self.counts[:value] + (self.counts[value] + 1,) + self.counts[value + 1:]

    def expected_loss(self, prediction, total):
        return 1 - Fraction(self.counts[prediction], total)

    def risk(self, total):
        return 1 - Fraction(max(self.counts), total)


class Posterior:
    """Uniform finite grammar posterior; local probes factor by operator."""

    def __init__(self, operators, width, modulus, observations, targets):
        self.modulus, self.targets = modulus, targets
        self.pools = (
            RulePool("A", width, modulus, observations),
            RulePool("B", width, modulus, observations, 1 if operators >= 2 else 0),
            RulePool("C", width, modulus, observations, 1 if operators >= 3 else 0),
        )
        self.total = self.pools[0].count * self.pools[1].count * self.pools[2].count
        self.histograms = (Histogram(modulus), Histogram(modulus), Histogram(modulus), Histogram(modulus), Histogram(modulus), Histogram(modulus))
        self.walk(0, ())

    def walk(self, position, rules):
        if position == 3:
            return self.record(rules, 0)
        return self.branches(position, rules, self.pools[position].entries)

    def branches(self, position, rules, remaining):
        if remaining == ():
            return
        self.walk(position + 1, rules + (remaining[0],))
        return self.branches(position, rules, remaining[1:])

    def record(self, rules, position):
        if position == 6:
            return
        self.histograms[position].add(self.targets[position].reduce(rules, self.modulus))
        return self.record(rules, position + 1)

    def losses(self, predictions, offset=0, position=0):
        if position == 3:
            return (Fraction(0), Fraction(0))
        histogram = self.histograms[offset + position]
        expected, risk = self.losses(predictions, offset, position + 1)
        return (expected + histogram.expected_loss(predictions[position], self.total), risk + histogram.risk(self.total))

"""Bounded controller-owned transport and trusted scripted-policy trials."""

import json
import re
import sys

from .game import ProgramDiscovery


class Session:
    def __init__(self, source=None, sink=None):
        self.source = sys.stdin if source is None else source
        self.sink = sys.stdout if sink is None else sink
        self.game, self.remaining_lines = None, 24

    def start(self, configuration):
        match = re.fullmatch(r"recursive ([0-9]{1,8}) ([0-9]{1,8}) ([2-5]) ([1-3]) ([23]) ([0-9]) (chain|balanced) (distinct|repeated) ([0-2]) (7|11)", configuration)
        if match is None:
            raise ValueError("configuration: recursive SEMANTIC_SEED PRIVATE_RULE_SEED DEPTH OPERATORS WIDTH BUDGET SHAPE SHARING DEMONSTRATIONS MODULUS")
        self.game = ProgramDiscovery(*match.groups())
        return self.game.view()

    def run(self):
        if self.game is None:
            configuration = self.source.readline(512)
            if configuration == "":
                return
            try:
                self.sink.write(self.start(configuration.rstrip("\r\n")) + "\n")
            except ValueError as exc:
                self.sink.write(f"configuration_error: {exc}\n")
                return
        if self.remaining_lines == 0:
            self.sink.write("response_limit: unscored\n")
            self.sink.flush()
            return
        self.sink.flush()
        raw = self.source.readline(512)
        if raw == "":
            self.sink.write("incomplete_episode: unscored\n")
            self.sink.flush()
            return
        self.remaining_lines -= 1
        try:
            self.game.step(raw.rstrip("\r\n"))
        except ValueError as exc:
            self.sink.write(f"invalid_action: {exc}\n")
        if self.game.stage == "done":
            self.sink.write(json.dumps(("recursive_result", self.game.result, ("actions", self.game.actions), ("observations", self.game.observations))) + "\n")
            self.sink.flush()
            return
        self.sink.write(self.game.view() + "\n")
        return self.run()


class Replay:
    def __init__(self, configuration):
        self.controller = Session()
        self.controller.start(configuration)
        self.count = 0

    def consume(self, actions):
        if actions == ():
            if self.controller.game.stage != "done":
                raise ValueError("incomplete replay")
            return (self.controller.game.observations, self.controller.game.result)
        if self.count >= 10:
            raise ValueError("replay exceeds query and answer bound")
        self.controller.game.step(actions[0])
        self.count += 1
        return self.consume(actions[1:])


class Trial:
    def __init__(self, configuration, policy):
        self.controller = Session()
        self.controller.start(configuration)
        self.configuration, self.policy = configuration, policy
        self.status, self.events = "open", ()
        self.remaining_calls = 24

    def run(self):
        game = self.controller.game
        if game.stage == "done":
            self.status = "scored"
            return self.record()
        if self.remaining_calls == 0:
            self.status = "response_limit_unscored"
            return self.record()
        self.remaining_calls -= 1
        observation = game.view()
        raw = self.policy.act(observation)
        self.events += (("observation", observation), ("response", raw))
        try:
            transition = game.step(raw)
        except ValueError as exc:
            self.events += (("invalid_action", str(exc)),)
        else:
            self.events += (("transition", transition),)
        return self.run()

    def record(self):
        return (("schema", "recursive-program-trial/1"), ("configuration", self.configuration), ("status", self.status), ("events", self.events), ("actions", self.controller.game.actions), ("metrics", self.controller.game.result))

"""Exact belief-state planning over hidden defender procedures.

The planning horizon counts probes and teaching interactions. The model depth
inside each defender is a separate, epistemic axis. Only public observations
condition this belief state; the realized controller profile is never consulted.
"""

from fractions import Fraction


class Belief:
    def __init__(self, records):
        total = self.total(records)
        if total <= 0:
            raise ValueError("empty or impossible procedure belief")
        self.records = self.normalize(records, total)

    def total(self, records):
        if records == ():
            return Fraction(0)
        if records[0][2] < 0:
            raise ValueError("negative procedure weight")
        return records[0][2] + self.total(records[1:])

    def normalize(self, records, total):
        if records == ():
            return ()
        identifier, defender, weight = records[0]
        if weight == 0:
            return self.normalize(records[1:], total)
        return ((identifier, defender, weight / total),) + self.normalize(records[1:], total)

    def size(self, records=None):
        if records is None:
            records = self.records
        if records == ():
            return 0
        return 1 + self.size(records[1:])

    def signature(self, records=None):
        if records is None:
            records = self.records
        if records == ():
            return ()
        identifier, defender, weight = records[0]
        return ((identifier, defender.depth, defender.cost, defender.credibility, weight),) + self.signature(records[1:])

    def responses(self, context, message, records=None):
        if records is None:
            records = self.records
        if records == ():
            return (Fraction(0), Fraction(0), Fraction(0))
        identifier, defender, weight = records[0]
        a, b, v = self.responses(context, message, records[1:])
        action = defender.choose(context, message)
        return (a + (weight if action == 0 else 0), b + (weight if action == 1 else 0), v + (weight if action == 2 else 0))

    def expected_loss(self, context, message, world, records=None):
        if records is None:
            records = self.records
        if records == ():
            return Fraction(0)
        identifier, defender, weight = records[0]
        loss = defender.loss(defender.choose(context, message), world)
        return weight * loss + self.expected_loss(context, message, world, records[1:])

    def survivors(self, context, message, response, world, learning, records):
        if records == ():
            return ()
        identifier, defender, weight = records[0]
        tail = self.survivors(context, message, response, world, learning, records[1:])
        if defender.choose(context, message) != response:
            return tail
        if learning == "adaptive":
            defender = defender.learn(context, message, world)
        return ((identifier, defender, weight),) + tail

    def condition(self, context, message, response, world, learning="frozen"):
        return Belief(self.survivors(context, message, response, world, learning, self.records))


class ControlPlan:
    def __init__(self, contexts, worlds, target, target_world, interaction_cost="1/50", learning="adaptive"):
        self.contexts, self.worlds = contexts, worlds
        self.target, self.target_world = target, target_world
        self.interaction_cost, self.learning = Fraction(interaction_cost), learning
        self.keys, self.cached_values = (), ()

    def validate(self, action, remaining):
        mode, case, message = action
        if mode == "attack":
            context, world = self.target, self.target_world
            if case != 0:
                raise ValueError("target has no calibration case index")
        elif mode == "probe" or mode == "teach":
            if remaining <= 0:
                raise ValueError("interaction budget exhausted")
            if case < 0 or self.contexts[case:] == ():
                raise ValueError("unknown calibration case")
            context, world = self.contexts[case], self.worlds[case]
        else:
            raise ValueError("unknown control action")
        if message < 0 or context.masks[message:] == ():
            raise ValueError("unknown message")
        if context.masks[message] & (1 << world) == 0:
            raise ValueError("message is false in the disclosed world")

    def targets(self, belief, message=0):
        if self.target.masks[message:] == ():
            return ()
        tail = self.targets(belief, message + 1)
        if self.target.masks[message] & (1 << self.target_world) == 0:
            return tail
        action = ("attack", 0, message)
        return ((action, belief.expected_loss(self.target, message, self.target_world)),) + tail

    def branch(self, belief, remaining, mode, case, message, response, probability):
        if probability == 0:
            return Fraction(0)
        learning = self.learning if mode == "teach" else "frozen"
        next_belief = belief.condition(self.contexts[case], message, response, self.worlds[case], learning)
        return probability * self.value(next_belief, remaining - 1)

    def action_value(self, belief, remaining, action):
        self.validate(action, remaining)
        mode, case, message = action
        if mode == "attack":
            return belief.expected_loss(self.target, message, self.target_world)
        a, b, v = belief.responses(self.contexts[case], message)
        return (-self.interaction_cost
                + self.branch(belief, remaining, mode, case, message, 0, a)
                + self.branch(belief, remaining, mode, case, message, 1, b)
                + self.branch(belief, remaining, mode, case, message, 2, v))

    def interactions(self, belief, remaining, case=0, message=0):
        if remaining == 0 or self.contexts[case:] == ():
            return ()
        context = self.contexts[case]
        if context.masks[message:] == ():
            return self.interactions(belief, remaining, case + 1, 0)
        tail = self.interactions(belief, remaining, case, message + 1)
        if context.masks[message] & (1 << self.worlds[case]) == 0:
            return tail
        probe, teach = ("probe", case, message), ("teach", case, message)
        return ((probe, self.action_value(belief, remaining, probe)), (teach, self.action_value(belief, remaining, teach))) + tail

    def best(self, choices):
        if choices[1:] == ():
            return choices[0]
        following = self.best(choices[1:])
        # Earlier actions win exact ties. Terminal choices precede interactions.
        return choices[0] if choices[0][1] >= following[1] else following

    def choose(self, belief, remaining):
        if remaining < 0 or remaining > 3:
            raise ValueError("control horizon outside finite domain")
        key = (belief.signature(), remaining)
        if self.keys.count(key) != 0:
            return self.cached_values[self.keys.index(key)]
        choices = self.targets(belief) + self.interactions(belief, remaining)
        result = self.best(choices)
        self.keys += (key,)
        self.cached_values += (result,)
        return result

    def value(self, belief, remaining):
        return self.choose(belief, remaining)[1]

"""Independent rational reference for finite recursive communication.

Only Fraction is imported. World/message joint weights are expanded afresh;
neither the production semantics nor its caches or update methods are reused.
This is an exhaustive mathematical reference, not evidence about model strategy.
"""

from fractions import Fraction


class ReferenceSemantics:
    def __init__(self, prior="5/7", masks=(3, 1), power=1, floor="0"):
        self.prior = Fraction(prior)
        self.masks = masks
        self.floor = Fraction(floor)
        if self.prior <= 0 or self.prior >= 1 or self.floor < 0:
            raise ValueError("interior prior and nonnegative selection floor required")
        if str(power) != "1" and str(power) != "2" and str(power) != "3":
            raise ValueError("power must be one, two, or three")
        self.power = int(power)
        self.validate_masks(masks)
        if sum(self.support(0)) == 0 or sum(self.support(1)) == 0:
            raise ValueError("each world requires a truthful available message")

    def validate_masks(self, remaining):
        if remaining == ():
            return
        if remaining[0] != 1 and remaining[0] != 2 and remaining[0] != 3:
            raise ValueError("truth masks must be one, two, or three")
        return self.validate_masks(remaining[1:])

    def support(self, world, position=0):
        if self.masks[position:] == ():
            return ()
        weight = Fraction(1) if self.masks[position] & (1 << world) else Fraction(0)
        return (weight,) + self.support(world, position + 1)

    def normalize(self, weights, total):
        if weights == ():
            return ()
        return (weights[0] / total,) + self.normalize(weights[1:], total)

    def preference_weights(self, depth, credibility, goal, world, position=0):
        if self.masks[position:] == ():
            return ()
        if self.masks[position] & (1 << world):
            a, b = self.joint(depth - 1, credibility, position)
            if a + b == 0:
                raise ValueError("undefined listener at zero-probability message")
            desired = (a, b)[world] if goal == "cooperative" else (b, a)[world]
            weight = self.floor + (desired / (a + b)) ** self.power
        else:
            weight = Fraction(0)
        return (weight,) + self.preference_weights(depth, credibility, goal, world, position + 1)

    def source(self, depth, credibility, goal, world):
        if depth < 1 or depth > 6 or world < 0 or world > 1:
            raise ValueError("source depth or world outside finite domain")
        if goal != "cooperative" and goal != "adversarial":
            raise ValueError("unknown source objective")
        credibility = Fraction(credibility)
        if credibility < 0 or credibility > 1:
            raise ValueError("credibility outside unit interval")
        weights = self.preference_weights(depth, credibility, goal, world)
        total = sum(weights)
        if total == 0:
            weights = self.support(world)
            total = sum(weights)
        return self.normalize(weights, total)

    def joint(self, depth, credibility, message):
        if depth == 0:
            a = self.prior if self.masks[message] & 1 else Fraction(0)
            b = 1 - self.prior if self.masks[message] & 2 else Fraction(0)
            return (a, b)
        cooperative_a = self.source(depth, credibility, "cooperative", 0)[message]
        adversarial_a = self.source(depth, credibility, "adversarial", 0)[message]
        cooperative_b = self.source(depth, credibility, "cooperative", 1)[message]
        adversarial_b = self.source(depth, credibility, "adversarial", 1)[message]
        a = self.prior * (credibility * cooperative_a + (1 - credibility) * adversarial_a)
        b = (1 - self.prior) * (credibility * cooperative_b + (1 - credibility) * adversarial_b)
        return (a, b)

    def listener(self, depth, credibility, message):
        if depth < 0 or depth > 6 or message < 0 or self.masks[message:] == ():
            raise ValueError("listener depth or message outside finite domain")
        credibility = Fraction(credibility)
        if credibility < 0 or credibility > 1:
            raise ValueError("credibility outside unit interval")
        a, b = self.joint(depth, credibility, message)
        if a + b == 0:
            raise ValueError("cannot condition on zero-probability message")
        return a / (a + b)

    def credibility_after(self, depth, credibility, message, world):
        credibility = Fraction(credibility)
        cooperative = self.source(max(1, depth), credibility, "cooperative", world)[message]
        adversarial = self.source(max(1, depth), credibility, "adversarial", world)[message]
        a = credibility * cooperative
        b = (1 - credibility) * adversarial
        if a + b == 0:
            raise ValueError("cannot update from zero-probability feedback")
        return a / (a + b)

"""Finite recursive speaker/listener models and an explicit adaptive defender.

Depth is epistemic: a source predicts a lower-depth listener, and a listener
conditions on the source's resulting message-selection policy. It is unrelated
to the recursion used by an implementation to traverse a search tree.
"""

from fractions import Fraction


class Semantics:
    def __init__(self, prior="5/7", masks=(3, 1), power=1, floor="0"):
        self.prior, self.floor = Fraction(prior), Fraction(floor)
        if self.prior <= 0 or self.prior >= 1 or self.floor < 0:
            raise ValueError("interior prior and nonnegative selection floor required")
        if str(power) != "1" and str(power) != "2" and str(power) != "3":
            raise ValueError("power must be one, two, or three")
        if masks == () or masks[4:] != ():
            raise ValueError("one to four message masks required")
        self.masks, self.power = masks, int(power)
        self.validate_masks(masks)
        if sum(self.support(0)) == 0 or sum(self.support(1)) == 0:
            raise ValueError("each world requires a truthful available message")
        self.source_keys, self.source_values = (), ()
        self.listener_keys, self.listener_values = (), ()

    def validate_masks(self, remaining):
        if remaining == ():
            return
        if remaining[0] != 1 and remaining[0] != 2 and remaining[0] != 3:
            raise ValueError("truth masks must be one, two, or three")
        return self.validate_masks(remaining[1:])

    def support(self, world, position=0):
        if self.masks[position:] == ():
            return ()
        value = Fraction(1) if self.masks[position] & (1 << world) else Fraction(0)
        return (value,) + self.support(world, position + 1)

    def weights(self, depth, credibility, goal, world, position=0):
        if self.masks[position:] == ():
            return ()
        weight = Fraction(0)
        if self.masks[position] & (1 << world):
            p = self.listener(depth - 1, credibility, position)
            correct = p if world == 0 else 1 - p
            desired = correct if goal == "cooperative" else 1 - correct
            weight = self.floor + desired ** self.power
        return (weight,) + self.weights(depth, credibility, goal, world, position + 1)

    def normalize(self, weights, total):
        if weights == ():
            return ()
        return (weights[0] / total,) + self.normalize(weights[1:], total)

    def source(self, depth, credibility, goal, world):
        if depth < 1 or depth > 6 or (world != 0 and world != 1):
            raise ValueError("source depth or world outside finite domain")
        if goal != "cooperative" and goal != "adversarial":
            raise ValueError("unknown source objective")
        credibility = Fraction(credibility)
        if credibility < 0 or credibility > 1:
            raise ValueError("credibility outside unit interval")
        key = (depth, credibility, goal, world)
        if self.source_keys.count(key) != 0:
            return self.source_values[self.source_keys.index(key)]
        weights = self.weights(depth, credibility, goal, world)
        total = sum(weights)
        if total == 0:
            weights = self.support(world)
            total = sum(weights)
        result = self.normalize(weights, total)
        self.source_keys += (key,)
        self.source_values += (result,)
        return result

    def listener(self, depth, credibility, message):
        if depth < 0 or depth > 6 or message < 0 or self.masks[message:] == ():
            raise ValueError("listener depth or message outside finite domain")
        credibility = Fraction(credibility)
        if credibility < 0 or credibility > 1:
            raise ValueError("credibility outside unit interval")
        key = (depth, credibility, message)
        if self.listener_keys.count(key) != 0:
            return self.listener_values[self.listener_keys.index(key)]
        if depth == 0:
            a = self.prior if self.masks[message] & 1 else Fraction(0)
            b = 1 - self.prior if self.masks[message] & 2 else Fraction(0)
        else:
            ca = self.source(depth, credibility, "cooperative", 0)[message]
            aa = self.source(depth, credibility, "adversarial", 0)[message]
            cb = self.source(depth, credibility, "cooperative", 1)[message]
            ab = self.source(depth, credibility, "adversarial", 1)[message]
            a = self.prior * (credibility * ca + (1 - credibility) * aa)
            b = (1 - self.prior) * (credibility * cb + (1 - credibility) * ab)
        if a + b == 0:
            raise ValueError("cannot condition on zero-probability message")
        result = a / (a + b)
        self.listener_keys += (key,)
        self.listener_values += (result,)
        return result

    def credibility_after(self, depth, credibility, message, world):
        credibility = Fraction(credibility)
        cooperative = self.source(max(1, depth), credibility, "cooperative", world)[message]
        adversarial = self.source(max(1, depth), credibility, "adversarial", world)[message]
        a, b = credibility * cooperative, (1 - credibility) * adversarial
        if a + b == 0:
            raise ValueError("cannot update from zero-probability feedback")
        return a / (a + b)


class Defender:
    """A supplied procedure family with explicit source-belief learning.

Actions 0 and 1 commit to A and B. Action 2 purchases a perfect verification.
The learning method returns a new state; probing an old state cannot alter it.
"""

    def __init__(self, depth=1, cost="1/2", credibility="1/2"):
        if depth < 0 or depth > 6:
            raise ValueError("defender depth outside finite domain")
        self.depth, self.cost, self.credibility = depth, Fraction(cost), Fraction(credibility)
        if self.cost < 0 or self.cost > 1 or self.credibility < 0 or self.credibility > 1:
            raise ValueError("invalid defender cost or source belief")

    def choose(self, context, message):
        p = context.listener(self.depth, self.credibility, message)
        if self.cost < min(p, 1 - p):
            return 2
        return 0 if p >= Fraction(1, 2) else 1

    def loss(self, action, world):
        if action == 2:
            return self.cost
        if action == 0 or action == 1:
            return Fraction(0) if action == world else Fraction(1)
        raise ValueError("unknown defender procedure")

    def learn(self, context, message, world):
        credibility = context.credibility_after(self.depth, self.credibility, message, world)
        return Defender(self.depth, self.cost, credibility)

    def row(self):
        return (self.depth, str(self.cost), str(self.credibility))

"""Provider-neutral OpenAI-compatible chat completion clients.

The arena deliberately keeps the provider client on the host.  Generated agent
containers never receive the API key and only execute the actions returned by the
client.
"""
from __future__ import annotations

import json
import random
import socket
import time
from collections.abc import Callable, Mapping
from dataclasses import dataclass
from email.utils import parsedate_to_datetime
from datetime import UTC, datetime
from pathlib import Path
from typing import Any
from urllib import error, request
from urllib.parse import urlsplit

from .secrets import (
    PROVIDER_DEFAULT_BASE,
    PROVIDER_ENV,
    ProviderCreds,
    redact_text,
    resolve_provider,
)

PROVIDERS: dict[str, dict[str, str | None]] = {
    name: {
        "api_base": base,
        "key_env": env_names[0],
    }
    for name, base in PROVIDER_DEFAULT_BASE.items()
    for env_names in [PROVIDER_ENV[name]]
}

# Keep this alias available to callers that want the resolved profile type
# without importing the secrets module directly.
ResolvedProvider = ProviderCreds


class _RejectRedirectHandler(request.HTTPRedirectHandler):
    """Do not forward authenticated requests to any redirected destination."""

    def redirect_request(self, req, fp, code, msg, headers, newurl):  # type: ignore[no-untyped-def]
        raise error.HTTPError(req.full_url, code, "authenticated redirects are disabled", headers, None)


_NO_REDIRECT_OPENER = request.build_opener(_RejectRedirectHandler)


def open_no_redirect(req: request.Request, timeout: float):
    """Open an authenticated request without following any HTTP redirect."""

    return _NO_REDIRECT_OPENER.open(req, timeout=timeout)


def require_https(url: str) -> None:
    """Require an absolute HTTPS endpoint for provider traffic."""

    parsed = urlsplit(url)
    if (
        parsed.scheme.lower() != "https"
        or not parsed.hostname
        or parsed.username is not None
        or parsed.password is not None
    ):
        raise ValueError("provider endpoints must use an absolute HTTPS URL without URL credentials")


@dataclass
class Completion:
