    response_headers: dict[str, str]
    status_code: int | None = None
    reasoning_content_length: int | None = None
    provider: str = ""
    upstream_provider: str | None = None


class ProviderError(RuntimeError):
    """A sanitized provider failure.

    ``body`` is intentionally capped and sanitized before it is stored.  The
    exception never includes the Authorization header or the supplied key.
    """

    def __init__(
        self,
        message: str,
        *,
        status_code: int | None = None,
        body: str = "",
        request_id: str | None = None,
        response_headers: Mapping[str, str] | None = None,
        retryable: bool = False,
        attempts: int = 1,
    ) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.body = body
        self.request_id = request_id
        self.response_headers = dict(response_headers or {})
        self.retryable = retryable
        self.attempts = attempts


@dataclass
class ProviderAttempt:
    """A sanitized record of one failed HTTP attempt."""

    attempted_at: str
    status_code: int | None
    error_type: str
    body: str
    request_id: str | None
    retryable: bool
    attempt: int
    elapsed_ms: int = 0
    response_headers: dict[str, str] | None = None

    def as_dict(self) -> dict[str, Any]:
        return {
            "attempted_at": self.attempted_at,
            "status_code": self.status_code,
            "error_type": self.error_type,
            "body": self.body,
            "request_id": self.request_id,
            "retryable": self.retryable,
            "attempt": self.attempt,
            "elapsed_ms": self.elapsed_ms,
            "response_headers": dict(self.response_headers or {}),
        }


def utc_now() -> str:
    return datetime.now(UTC).isoformat()


def _redact_text(text: str, secret: str | None = None, limit: int = 4000) -> str:
    """Return a bounded provider error body without credentials."""

    return redact_text(text[:limit], [secret] if secret else None)


def _safe_headers(
    headers: Mapping[str, str], secret: str | None = None
) -> dict[str, str]:
    unsafe = {"authorization", "proxy-authorization", "cookie", "set-cookie", "x-api-key"}
    return {
        str(key): redact_text(str(value), [secret] if secret else None)
        for key, value in headers.items()
        if str(key).lower() not in unsafe and "token" not in str(key).lower()
    }


def provider_auth_headers(provider: str, api_key: str) -> dict[str, str]:
    """Return the provider-specific API-key header for OpenAI-compatible APIs.

    Authentication policy lives here so normal requests and provider preflight
    use identical rules. Most providers use Bearer auth; YepAPI specifies the
    dedicated ``x-api-key`` header.
    """

    normalized = provider.strip().lower()
    if normalized == "yepapi":
        return {"x-api-key": api_key}
    return {"Authorization": f"Bearer {api_key}"}


def resolve_credentials(
    provider: str,
    *,
    api_key: str | None = None,
    api_key_env: str | None = None,
    api_base: str | None = None,
    secret_path: Path | None = None,
    environ: Mapping[str, str] | None = None,
) -> tuple[str, str]:
    """Resolve ``(api_key, environment_name)`` without ever printing it."""

    env = environ if environ is not None else __import__("os").environ
    credentials = resolve_provider(
        provider,
        api_key=api_key,
        api_key_env=api_key_env,
        api_base=api_base,
        secret_path=secret_path,
        environ=env,
    )
    if api_key:
        selected_env = api_key_env or PROVIDER_ENV[credentials.name][0]
    elif api_key_env and env.get(api_key_env):
        selected_env = api_key_env
    else:
        selected_env = next(
            (name for name in PROVIDER_ENV[credentials.name] if env.get(name)),
            api_key_env or PROVIDER_ENV[credentials.name][0],
        )
    return credentials.api_key, selected_env


def resolve_api_base(
    provider: str,
    api_base: str | None = None,
    *,
    secret_path: Path | None = None,
) -> str:
    # require_key=False lets planning and review code resolve a file/profile
    # endpoint without requiring a credential until the live request starts.
    credentials = resolve_provider(
        provider,
        api_base=api_base,
        secret_path=secret_path,
        require_key=False,
    )
    require_https(credentials.api_base)
    return credentials.api_base


def chat_completions_url(api_base: str) -> str:
    """Normalize a base URL to the required OpenAI-compatible endpoint."""

    base = api_base.rstrip("/")
    url = base if base.endswith("/chat/completions") else f"{base}/chat/completions"
    require_https(url)
    return url


def responses_url(api_base: str) -> str:
    """Normalize a base URL to the OpenAI-Responses-compatible endpoint.

    Atria-Dawn-Preview exposes controlled reasoning only here (nested
    ``reasoning: {effort}``); its Chat Completions surface has no reasoning
    field, which is why the Chat-Completions campaign is provider-default.
    """

    base = api_base.rstrip("/")
    url = base if base.endswith("/responses") else f"{base}/responses"
    require_https(url)
    return url


def _content_from_responses_output(data: Mapping[str, Any]) -> str:
    """Extract the answer text from an OpenAI-Responses-shaped body.

    Tolerant of the shapes an OpenAI-Responses-compatible server may return:
    the ``output_text`` convenience field, text directly on an output item, a
    string ``content``, or a list of typed ``content`` parts. The only items and
    parts deliberately skipped are reasoning/chain-of-thought ones, so a leading
    reasoning item never masquerades as the answer and an unexpectedly-typed
    message item is still collected rather than silently dropped.
    """

    convenience = data.get("output_text")
    if isinstance(convenience, str) and convenience.strip():
        return convenience
    output = data.get("output")
    if not isinstance(output, list):
        return ""
    pieces: list[str] = []
    for item in output:
        if not isinstance(item, dict):
            continue
        item_type = item.get("type")
        if isinstance(item_type, str) and "reason" in item_type.lower():
            continue  # never fold a reasoning item into the visible answer
        if isinstance(item.get("text"), str):
            pieces.append(item["text"])
        content = item.get("content")
        if isinstance(content, str):
            pieces.append(content)
        elif isinstance(content, list):
            for part in content:
                if isinstance(part, str):
                    pieces.append(part)
                elif isinstance(part, dict):
                    part_type = part.get("type")
                    if isinstance(part_type, str) and "reason" in part_type.lower():
                        continue
                    if isinstance(part.get("text"), str):
                        pieces.append(part["text"])
    return "".join(pieces)



def _content_from_message(message: Any) -> str:
    content = message.get("content") if isinstance(message, dict) else None
    if isinstance(content, str):
        return content
    # Some OpenAI-compatible providers return a list of typed content parts.
    if isinstance(content, list):
        pieces: list[str] = []
        for part in content:
            if isinstance(part, str):
                pieces.append(part)
            elif isinstance(part, dict) and isinstance(part.get("text"), str):
                pieces.append(part["text"])
        return "".join(pieces)
    if content is None:
        return ""
    return str(content)


def _reasoning_content_length(message: Any) -> int | None:
    """Return the length of provider reasoning content when it is exposed."""

    if not isinstance(message, dict):
        return None
    for key in ("reasoning_content", "reasoning", "thinking"):
        value = message.get(key)
        if value is None:
            continue
        if isinstance(value, str):
            return len(value)
        if isinstance(value, list):
            return len(_content_from_message({"content": value}))
        return len(str(value))
    return None


def _request_id(headers: Mapping[str, str], data: Mapping[str, Any]) -> str | None:
    for key, value in headers.items():
        if key.lower() in {"x-request-id", "request-id", "openrouter-request-id"}:
            return str(value)
    value = data.get("id")
    return str(value) if value is not None else None


def _is_retryable_internal_api_error(data: Mapping[str, Any]) -> bool:
    """Recognize explicit transient API-gateway failures without retrying auth/quota.

    Some OpenAI-compatible gateways return ``{"error":{"type":"api_error",
    "code":"internal","message":"fetch failed"}}`` as JSON instead of an
    HTTP 5xx. Treat only that explicit internal-error class as transient; invalid
    credentials, insufficient quota, and malformed requests remain non-retryable.
    """

    error_value = data.get("error")
    if not isinstance(error_value, Mapping):
        return False
    error_type = str(error_value.get("type", "")).strip().lower()
    error_code = str(error_value.get("code", "")).strip().lower()
    message = str(error_value.get("message", "")).strip().lower()
    return error_type == "api_error" and (
        error_code == "internal" or message == "fetch failed"
    )


def _validate_request_extra(extra: Mapping[str, Any] | None) -> dict[str, Any]:
    if extra is None:
        return {}
    if not isinstance(extra, Mapping):
        raise ValueError("request-extra must be a JSON object")
    forbidden = {
        "model",
        "messages",
        "authorization",
        "headers",
        "stream",
        "temperature",
        "top_p",
        "max_tokens",
    }
    blocked = sorted(str(key) for key in extra if str(key).lower() in forbidden)
    if blocked:
        raise ValueError(
            "request-extra may not override protected fields: " + ", ".join(blocked)
        )
    return dict(extra)


# Providers whose OpenAI-compatible endpoint expects a completion-size key
# other than the default ``max_tokens``. Inception Labs Mercury documents
# ``max_completion_tokens`` (see docs.inceptionlabs.ai). Keyed by the
# registered provider name; anything unlisted keeps ``max_tokens``.
_MAX_TOKENS_KEY: dict[str, str] = {
    "mercury": "max_completion_tokens",
}


class ProviderClient:
    """A small urllib-based client for OpenAI-compatible chat APIs."""

    def __init__(
        self,
        provider: str,
        api_key: str,
        *,
        api_base: str | None = None,
        timeout: float = 120.0,
        max_retries: int = 3,
        backoff_base: float = 0.5,
        backoff_max: float = 8.0,
        jitter: float = 0.25,
        max_http_attempts: int | None = None,
        min_interval_seconds: float = 0.0,
        opener: Any = None,
        sleep: Callable[[float], None] = time.sleep,
        random_fn: Callable[[], float] = random.random,
        error_logger: Callable[[dict[str, Any]], None] | None = None,
    ) -> None:
        if not api_key:
            raise ValueError("api_key must not be empty")
        self.provider = provider
        self.api_key = api_key
        self.api_base = resolve_api_base(provider, api_base)
        self.timeout = timeout
        self.max_retries = max(0, int(max_retries))
        if self.max_retries > 5:
            raise ValueError("max_retries must be at most 5 (six attempts maximum)")
        if max_http_attempts is not None and int(max_http_attempts) < 1:
            raise ValueError("max_http_attempts must be positive when provided")
        self.max_http_attempts = (
            int(max_http_attempts) if max_http_attempts is not None else None
        )
        if float(min_interval_seconds) < 0:
            raise ValueError("min_interval_seconds must not be negative")
        self.min_interval_seconds = float(min_interval_seconds)
        self._last_request_started_at: float | None = None
        self._rate_limit_pause_until = 0.0
        self.http_attempts_used = 0
        self.backoff_base = max(0.0, float(backoff_base))
        self.backoff_max = max(0.0, float(backoff_max))
        self.jitter = max(0.0, float(jitter))
        self.opener = opener or open_no_redirect
        self.sleep = sleep
        self.random_fn = random_fn
        self.error_logger = error_logger
        self.last_retry_count = 0
        self.last_attempts: list[ProviderAttempt] = []
        self.last_attempt_logs: list[dict[str, Any]] = []
        self.last_http_attempts = 0

    def headers(self) -> dict[str, str]:
        headers = {
            **provider_auth_headers(self.provider, self.api_key),
            "Content-Type": "application/json",
        }
        if self.provider == "openrouter":
            headers.update(
                {
                    "HTTP-Referer": "https://github.com/StrangeTcy/rl_eval_generator",
                    "X-OpenRouter-Title": "rl_eval_generator arena",
                }
            )
        return headers

    def _log_attempt(self, record: dict[str, Any]) -> None:
        self.last_attempt_logs.append(dict(record))
        if self.error_logger:
            self.error_logger(record)

    def _record_failure(self, attempt: ProviderAttempt) -> None:
        self.last_attempts.append(attempt)
        self._log_attempt(attempt.as_dict())

    def _record_success(
        self,
        *,
        status_code: int | None,
        request_id: str | None,
        attempt: int,
        elapsed_ms: int,
        response_headers: Mapping[str, str] | None = None,
    ) -> None:
        self._log_attempt(
            {
                "attempted_at": utc_now(),
                "status_code": status_code,
                "error_type": "success",
                "body": "",
                "request_id": request_id,
                "retryable": False,
                "attempt": attempt,
                "elapsed_ms": elapsed_ms,
                "response_headers": dict(response_headers or {}),
            }
        )

    @staticmethod
    def _header_value(headers: Mapping[str, Any] | None, name: str) -> str | None:
        for key, value in (headers or {}).items():
            if str(key).lower() == name.lower():
                return str(value)
        return None

    def _observe_rate_limit_headers(
        self, headers: Mapping[str, Any] | None, *, status_code: int | None
    ) -> None:
        limit_text = self._header_value(headers, "x-rpm-limit")
        try:
            limit = float(limit_text) if limit_text is not None else 0.0
        except (TypeError, ValueError):
            limit = 0.0
        if limit > 0:
            self.min_interval_seconds = max(self.min_interval_seconds, 60.0 / limit)
        remaining_text = self._header_value(headers, "x-rpm-remaining")
        try:
            remaining = int(float(remaining_text)) if remaining_text is not None else None
        except (TypeError, ValueError):
            remaining = None
        if remaining is not None and remaining <= 0 and status_code is not None and 200 <= status_code < 300:
            # Atria documents a fixed minute boundary. Without a Retry-After
            # header on a successful response, reserve the next minute before
            # issuing another request.
            self._rate_limit_pause_until = max(
                self._rate_limit_pause_until, time.monotonic() + 60.0
            )

    def _wait_for_request_slot(self) -> None:
        now = time.monotonic()
        wait = max(0.0, self._rate_limit_pause_until - now)
        if self._last_request_started_at is not None:
            wait = max(
                wait,
                self.min_interval_seconds - (now - self._last_request_started_at),
            )
        if wait > 0:
            self.sleep(wait)
            # The injected sleeper used by offline tests may not advance the
            # monotonic clock; treat the requested wait as honored rather than
            # repeatedly scheduling the same pause.
            self._rate_limit_pause_until = min(
                self._rate_limit_pause_until, time.monotonic()
            )
        self._last_request_started_at = time.monotonic()

    def _backoff(self, retry_number: int, retry_after: float | None = None) -> None:
        if retry_after is not None:
            # Retry-After is an explicit provider instruction; do not add
            # jitter or silently shorten it.
            delay = retry_after
        else:
            delay = min(self.backoff_max, self.backoff_base * (2 ** max(0, retry_number - 1)))
            if self.jitter:
                delay = min(self.backoff_max, delay + self.jitter * self.random_fn())
        if delay > 0:
            self.sleep(delay)
        # Retry-After is measured from the failed response. When it already
        # exceeds the adaptive RPM interval, do not add a second pacing sleep
        # before the next attempt (this also keeps injected/fake sleepers
        # deterministic in offline tests).
        if retry_after is not None and retry_after >= self.min_interval_seconds:
            self._last_request_started_at = time.monotonic() - self.min_interval_seconds

    @staticmethod
    def _retry_after_seconds(headers: Mapping[str, Any] | None) -> float | None:
        value = next(
            (str(item) for key, item in (headers or {}).items() if str(key).lower() == "retry-after"),
            None,
        )
        if value is None:
            return None
        try:
            return max(0.0, float(value))
        except (TypeError, ValueError, OverflowError):
            try:
                date = parsedate_to_datetime(value)
                if date.tzinfo is None:
                    date = date.replace(tzinfo=UTC)
                return max(0.0, (date - datetime.now(UTC)).total_seconds())
            except (TypeError, ValueError, OverflowError):
                return None

    def complete(
        self,
        *,
        model: str,
        messages: list[dict[str, Any]],
        max_tokens: int,
        temperature: float,
        top_p: float | None = None,
        request_extra: Mapping[str, Any] | None = None,
    ) -> Completion:
        """Make a completion request, retrying only explicitly transient errors."""

        if not model or not model.strip():
            raise ValueError("model must not be empty")
        extra = _validate_request_extra(request_extra)
        # Mercury's OpenAI-compatible endpoint documents ``max_completion_tokens``;
        # every other wired provider uses ``max_tokens``. ``request_extra`` may not
        # carry either protected key, so this is the single place the size is set.
        max_tokens_key = _MAX_TOKENS_KEY.get(self.provider, "max_tokens")
        payload: dict[str, Any] = {
            "model": model,
            "messages": messages,
            max_tokens_key: int(max_tokens),
            "temperature": float(temperature),
            "stream": False,
        }
        if top_p is not None:
            if not 0.0 < float(top_p) <= 1.0:
                raise ValueError("top_p must be greater than 0 and at most 1")
            payload["top_p"] = float(top_p)
        payload.update(extra)
        # Protected keys are checked above, and are assigned before extras.  The
        # explicit assignment also protects callers that pass a strange Mapping.
        payload["model"] = model
        payload["messages"] = messages
        payload["stream"] = False

        self.last_attempts = []
        self.last_attempt_logs = []
        self.last_retry_count = 0
        self.last_http_attempts = 0
        url = chat_completions_url(self.api_base)
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        headers = self.headers()

        for attempt_number in range(1, self.max_retries + 2):
            if self.max_http_attempts is not None and self.http_attempts_used >= self.max_http_attempts:
                failure = ProviderAttempt(
                    attempted_at=utc_now(),
                    status_code=None,
                    error_type="attempt_budget_exhausted",
                    body="provider HTTP attempt budget exhausted",
                    request_id=None,
                    retryable=False,
                    attempt=attempt_number,
                    elapsed_ms=0,
                )
                self._log_attempt(failure.as_dict())
                raise ProviderError(
                    "Provider HTTP attempt budget exhausted",
                    body=failure.body,
                    retryable=False,
                    attempts=self.http_attempts_used,
                )
            self._wait_for_request_slot()
            self.http_attempts_used += 1
            self.last_http_attempts += 1
            started = time.monotonic()
            response_status_code: int | None = None
            try:
                req = request.Request(url, data=body, headers=headers, method="POST")
                with self.opener(req, timeout=self.timeout) as response:
                    response_status_code = int(getattr(response, "status", 200))
                    response_body = response.read().decode("utf-8", errors="replace")
                    raw_response_headers = dict(response.headers.items())
                    self._observe_rate_limit_headers(
                        raw_response_headers, status_code=response_status_code
                    )
                    response_headers = _safe_headers(raw_response_headers, self.api_key)
                data = json.loads(response_body)
                if not isinstance(data, dict):
                    failure = ProviderAttempt(
                        attempted_at=utc_now(),
                        status_code=response_status_code,
                        error_type="invalid_response",
                        body=_redact_text(response_body, self.api_key),
                        request_id=None,
                        retryable=False,
                        attempt=attempt_number,
                        elapsed_ms=max(0, int(round((time.monotonic() - started) * 1000))),
                        response_headers=response_headers,
                    )
                    self._record_failure(failure)
                    raise ProviderError(
                        "Provider returned a non-object JSON response",
                        body=failure.body,
                        response_headers=response_headers,
                        attempts=attempt_number,
                    )
                if isinstance(data.get("error"), dict):
                    request_id = _request_id(response_headers, data)
                    retryable = (
                        response_status_code not in {401, 402, 403}
                        and _is_retryable_internal_api_error(data)
                    )
                    failure = ProviderAttempt(
                        attempted_at=utc_now(),
                        status_code=response_status_code,
                        error_type="api_error",
                        body=_redact_text(response_body, self.api_key),
                        request_id=request_id,
                        retryable=retryable,
                        attempt=attempt_number,
                        elapsed_ms=max(0, int(round((time.monotonic() - started) * 1000))),
                        response_headers=response_headers,
                    )
                    self._record_failure(failure)
                    if (
                        retryable
                        and attempt_number <= self.max_retries
                        and (
                            self.max_http_attempts is None
                            or self.http_attempts_used < self.max_http_attempts
                        )
                    ):
                        self.last_retry_count += 1
                        self._backoff(
                            attempt_number,
                            self._retry_after_seconds(raw_response_headers),
                        )
                        continue
                    raise ProviderError(
                        "Provider returned an API error",
                        status_code=response_status_code,
                        body=failure.body,
                        request_id=request_id,
                        response_headers=response_headers,
                        retryable=retryable,
                        attempts=attempt_number,
                    )
                choices = data.get("choices")
                if not isinstance(choices, list) or not choices or not isinstance(choices[0], dict):
                    request_id = _request_id(response_headers, data)
                    failure = ProviderAttempt(
                        attempted_at=utc_now(),
                        status_code=response_status_code,
                        error_type="invalid_response",
                        body=_redact_text(response_body, self.api_key),
                        request_id=request_id,
                        retryable=False,
                        attempt=attempt_number,
                        elapsed_ms=max(0, int(round((time.monotonic() - started) * 1000))),
                    )
                    self._record_failure(failure)
                    raise ProviderError(
                        "Provider response did not contain choices[0]",
                        body=failure.body,
                        request_id=request_id,
                        response_headers=response_headers,
                        attempts=attempt_number,
                    )
                choice = choices[0]
                message = choice.get("message", {})
                finish_reason = choice.get("finish_reason")
                usage = data.get("usage")
                reasoning_length = _reasoning_content_length(message)
                if reasoning_length is None:
                    reasoning_length = _reasoning_content_length(choice)
                latency_ms = max(0, int(round((time.monotonic() - started) * 1000)))
                request_id = _request_id(response_headers, data)
                self._record_success(
                    status_code=response_status_code,
                    request_id=request_id,
                    attempt=attempt_number,
                    elapsed_ms=latency_ms,
                    response_headers=response_headers,
                )
                return Completion(
                    content=_content_from_message(message),
                    requested_model=model,
                    resolved_model=str(data["model"]) if data.get("model") is not None else None,
                    finish_reason=str(finish_reason) if finish_reason is not None else None,
                    usage=dict(usage) if isinstance(usage, dict) else {},
                    raw_response=dict(data),
                    latency_ms=latency_ms,
                    request_id=request_id,
                    response_headers=response_headers,
                    status_code=response_status_code,
                    reasoning_content_length=reasoning_length,
                    provider=self.provider,
                    upstream_provider=(
                        str(data["provider"]) if data.get("provider") is not None else None
                    ),
                )
            except error.HTTPError as exc:
                try:
                    response_body = exc.read().decode("utf-8", errors="replace")
                except (AttributeError, OSError):
                    response_body = ""
                status = int(exc.code)
                raw_error_headers = dict(exc.headers.items()) if exc.headers else {}
                self._observe_rate_limit_headers(raw_error_headers, status_code=status)
                safe_headers = _safe_headers(raw_error_headers, self.api_key)
                request_id = _request_id(safe_headers, {})
                # Retry only rate limiting and server-side transient failures.
                # Authentication/quota (401/402/403) and client errors remain
                # non-retryable. Include 500/502 for gateways that surface an
                # upstream ``fetch failed`` as a conventional server response.
                retryable = status in {429, 500, 502, 503, 504}
                elapsed_ms = max(0, int(round((time.monotonic() - started) * 1000)))
                failure = ProviderAttempt(
                    attempted_at=utc_now(),
                    status_code=status,
                    error_type="http_error",
                    body=_redact_text(response_body, self.api_key),
                    request_id=request_id,
                    retryable=retryable,
                    attempt=attempt_number,
                    elapsed_ms=elapsed_ms,
                    response_headers=safe_headers,
                )
                self._record_failure(failure)
                if (
                    retryable
